return ['domain'=>'wp-agent-support-layer','plural-forms'=>NULL,'language'=>'','project-id-version'=>'WP Agent Support Layer 0.1.0','pot-creation-date'=>'2026-09-02T01:31:46+00:00','po-revision-date'=>'2026-09-01 20:00-0500','x-generator'=>'WP-CLI 2.12.0','messages'=>['WP Agent Support Layer'=>'WP Agent Support Layer','https://github.com/111x-SAS/wp-agent-support-layer'=>'https://github.com/111x-SAS/wp-agent-support-layer','Makes your site discoverable, readable and operable by AI agents and crawlers: Markdown delivery, Content Signals, AI crawler rules in robots.txt, llms.txt and agent manifests.'=>'Hace que tu sitio sea descubrible, legible y operable por agentes y crawlers de IA: entrega en Markdown, Content Signals, reglas para crawlers de IA en robots.txt, llms.txt y manifiestos de agente.','Mao Rodriguez'=>'Mao Rodriguez','https://111x.co'=>'https://111x.co','Exclude from the agent layer (Markdown, llms.txt, manifests).'=>'Excluir de la capa de agentes (Markdown, llms.txt, manifiestos).','Agent Support Layer'=>'Agent Support Layer','Exclude from the agent layer'=>'Excluir de la capa de agentes','Hides this item from the Markdown version, llms.txt and the agent manifest.'=>'Oculta este elemento de la versión Markdown, de llms.txt y del manifiesto de agente.','Settings'=>'Ajustes','You do not have permission to access this page.'=>'No tienes permiso para acceder a esta página.','Secondary menu'=>'Menú secundario','General'=>'General','Hourly'=>'Cada hora','Twice daily'=>'Dos veces al día','Daily'=>'Diario','Weekly'=>'Semanal','Content types'=>'Tipos de contenido','Content types exposed to agents'=>'Tipos de contenido expuestos a los agentes','Published items of these types get a Markdown version, appear in llms.txt and are declared in the agent manifest.'=>'Los elementos publicados de estos tipos obtienen una versión Markdown, aparecen en llms.txt y se declaran en el manifiesto de agente.','Regeneration interval'=>'Intervalo de regeneración','Markdown documents and discovery files are generated on this schedule, never when a post is saved.'=>'Los documentos Markdown y los archivos de descubrimiento se generan con esta programación, nunca al guardar una entrada.','Items per run'=>'Elementos por ejecución','Maximum number of items converted in one scheduled run. Large sites are processed over several runs.'=>'Número máximo de elementos convertidos en una ejecución programada. Los sitios grandes se procesan en varias ejecuciones.','WP Agent Support Layer requires PHP %1$s or newer. This site runs PHP %2$s.'=>'WP Agent Support Layer requiere PHP %1$s o superior. Este sitio usa PHP %2$s.','WP Agent Support Layer requires WordPress %1$s or newer. This site runs WordPress %2$s.'=>'WP Agent Support Layer requiere WordPress %1$s o superior. Este sitio usa WordPress %2$s.','You do not have permission to do this.'=>'No tienes permiso para hacer esto.','Generation status'=>'Estado de la generación','A generation run has been scheduled and will start in the background.'=>'Se ha programado una ejecución de generación que comenzará en segundo plano.','A full regeneration has been scheduled and will run in the background over one or more batches.'=>'Se ha programado una regeneración completa que se ejecutará en segundo plano en uno o varios lotes.','WP-Cron is disabled on this site (DISABLE_WP_CRON). Generation depends on a system cron calling wp-cron.php or on the "wp wpasl generate" WP-CLI command.'=>'WP-Cron está desactivado en este sitio (DISABLE_WP_CRON). La generación depende de un cron del sistema que llame a wp-cron.php o del comando WP-CLI "wp wpasl generate".','Eligible items'=>'Elementos elegibles','With a generated document'=>'Con documento generado','Pending'=>'Pendientes','Last run'=>'Última ejecución','Last completed cycle'=>'Último ciclo completado','Next scheduled run'=>'Próxima ejecución programada','Not scheduled'=>'No programada','Regenerate now'=>'Regenerar ahora','Regenerate everything'=>'Regenerar todo','Both actions run in the background. "Regenerate now" processes the next batch; "Regenerate everything" starts a new cycle over all eligible items.'=>'Ambas acciones se ejecutan en segundo plano. "Regenerar ahora" procesa el siguiente lote; "Regenerar todo" inicia un nuevo ciclo sobre todos los elementos elegibles.','Never'=>'Nunca','WP Agent Support Layer: the bundled HTML-to-Markdown library is missing. Install a release build, or run "composer run build" in the plugin directory.'=>'WP Agent Support Layer: falta la librería HTML a Markdown incluida. Instala una versión de release o ejecuta "composer run build" en el directorio del plugin.','Signals'=>'Señales','Search'=>'Búsqueda','Building a search index and showing links and short excerpts in results. Does not include AI-generated summaries.'=>'Construir un índice de búsqueda y mostrar enlaces y extractos breves en los resultados. No incluye resúmenes generados por IA.','AI input'=>'Entrada para IA','Using the content as input for AI models in real time: answer engines, retrieval-augmented generation, on-demand agents.'=>'Usar el contenido como entrada de modelos de IA en tiempo real: motores de respuestas, generación aumentada por recuperación, agentes bajo demanda.','AI training'=>'Entrenamiento de IA','Training or fine-tuning AI models. When set to No, the site also sends "noai, noimageai" in X-Robots-Tag and the robots meta tag.'=>'Entrenar o ajustar modelos de IA. Con No, el sitio envía además "noai, noimageai" en X-Robots-Tag y en la meta etiqueta robots.','These preferences are published in robots.txt (Content-Signal directive), in the Content-Signal HTTP header of every public response and as robots directives. They are declarations, not enforcement; use the Crawlers tab to decide which AI crawlers may fetch the site.'=>'Estas preferencias se publican en robots.txt (directiva Content-Signal), en la cabecera HTTP Content-Signal de cada respuesta pública y como directivas robots. Son declaraciones, no un bloqueo; usa la pestaña Crawlers para decidir qué crawlers de IA pueden acceder al sitio.','Yes'=>'Sí','No'=>'No','Content-Usage header'=>'Cabecera Content-Usage','Also send the experimental IETF AIPREF "Content-Usage" header (train-ai, search).'=>'Enviar también la cabecera experimental "Content-Usage" del IETF AIPREF (train-ai, search).','The AIPREF specification is still a draft; disable this if its syntax changes.'=>'La especificación AIPREF sigue siendo un borrador; desactívalo si su sintaxis cambia.','Crawlers'=>'Crawlers','Each AI crawler gets its own group in robots.txt. "Default" follows the Content Signals; choose Allow or Block to override a single crawler.'=>'Cada crawler de IA tiene su propio grupo en robots.txt. "Por defecto" sigue los Content Signals; elige Permitir o Bloquear para sobrescribir un crawler concreto.','Microsoft Copilot uses Bingbot and Google Gemini uses Google-Extended; they cannot be separated from regular search indexing beyond what those tokens allow.'=>'Microsoft Copilot usa Bingbot y Google Gemini usa Google-Extended; no pueden separarse de la indexación de búsqueda habitual más allá de lo que permiten esos tokens.','A physical robots.txt file exists in the site root. WordPress does not serve the generated rules; copy the text below into your file.'=>'Existe un archivo robots.txt físico en la raíz del sitio. WordPress no sirve las reglas generadas; copia el texto de abajo en tu archivo.','Current default: Block.'=>'Valor por defecto actual: Bloquear.','Current default: Allow.'=>'Valor por defecto actual: Permitir.','User-agent'=>'User-agent','Vendor'=>'Proveedor','Policy'=>'Política','Effective'=>'Efectiva','Documentation'=>'Documentación','Default'=>'Por defecto','Allow'=>'Permitir','Block'=>'Bloquear','Generated robots.txt'=>'robots.txt generado','Read-only preview of what WordPress serves at /robots.txt with the saved settings.'=>'Vista previa de solo lectura de lo que WordPress sirve en /robots.txt con los ajustes guardados.','Training crawlers'=>'Crawlers de entrenamiento','AI search crawlers'=>'Crawlers de búsqueda con IA','On-demand agents'=>'Agentes bajo demanda','Collect content to train or fine-tune models. Follows the "AI training" signal by default.'=>'Recopilan contenido para entrenar o ajustar modelos. Siguen la señal "Entrenamiento de IA" por defecto.','Index content for AI-powered search and answer engines. Follows the "Search" signal by default.'=>'Indexan contenido para buscadores y motores de respuestas con IA. Siguen la señal "Búsqueda" por defecto.','Fetch pages on behalf of a user during a conversation. Follows the "AI input" signal by default.'=>'Obtienen páginas en nombre de un usuario durante una conversación. Siguen la señal "Entrada para IA" por defecto.','A physical robots.txt file exists in the site root, so WordPress does not serve the generated one. Copy the rules from the Crawlers tab into that file.'=>'Existe un archivo robots.txt físico en la raíz del sitio, así que WordPress no sirve el generado. Copia las reglas de la pestaña Crawlers en ese archivo.','Published at %s: the site name, a description, an optional introduction and one section per content type linking to the Markdown version of each item.'=>'Publicado en %s: el nombre del sitio, una descripción, una introducción opcional y una sección por tipo de contenido con enlaces a la versión Markdown de cada elemento.','A physical llms.txt file exists in the site root and takes precedence over the generated one.'=>'Existe un archivo llms.txt físico en la raíz del sitio y tiene prioridad sobre el generado.','Site description'=>'Descripción del sitio','One or two sentences shown as the summary block. Defaults to the site tagline.'=>'Una o dos frases que se muestran como bloque de resumen. Por defecto, la descripción corta del sitio.','Introduction (Markdown)'=>'Introducción (Markdown)','Optional free text placed before the content sections: what the site is about, key products, how to get in touch.'=>'Texto libre opcional antes de las secciones de contenido: de qué trata el sitio, productos clave, cómo contactar.','Items per section'=>'Elementos por sección','Pages are listed by menu order, other types by publication date, newest first.'=>'Las páginas se listan por orden de menú; los demás tipos por fecha de publicación, primero los más recientes.','llms-full.txt'=>'llms-full.txt','Also publish /llms-full.txt with the full Markdown of every indexed item concatenated.'=>'Publicar también /llms-full.txt con el Markdown completo de todos los elementos indexados concatenados.','Useful for agents that want the whole site in one request. Disabled by default because the file can get large.'=>'Útil para agentes que quieren todo el sitio en una sola petición. Desactivado por defecto porque el archivo puede crecer mucho.','llms-full.txt size limit (MB)'=>'Límite de tamaño de llms-full.txt (MB)','When the limit is reached the file stops at the last complete item and ends with a note saying it was truncated.'=>'Al alcanzar el límite, el archivo se detiene en el último elemento completo y termina con una nota indicando que fue truncado.','Content index of %s.'=>'Índice de contenidos de %s.','Concatenated Markdown of the content indexed in %s.'=>'Markdown concatenado del contenido indexado en %s.','Truncated: this file reached its %1$s limit. The complete index is in %2$s.'=>'Truncado: este archivo alcanzó su límite de %1$s. El índice completo está en %2$s.','Manifests'=>'Manifiestos','JSON-LD manifest of the actions an agent can perform without authentication.'=>'Manifiesto JSON-LD de las acciones que un agente puede realizar sin autenticación.','OpenAPI 3.1 description of the public REST endpoints.'=>'Descripción OpenAPI 3.1 de los endpoints REST públicos.','RFC 9727 API catalog pointing to the OpenAPI document.'=>'Catálogo de API RFC 9727 que apunta al documento OpenAPI.','The manifests only declare what the site really exposes: search, listing and reading of the enabled content types through the REST API, Markdown delivery and llms.txt. Nothing that requires authentication is ever listed.'=>'Los manifiestos solo declaran lo que el sitio expone realmente: búsqueda, listado y lectura de los tipos de contenido habilitados a través de la API REST, entrega en Markdown y llms.txt. Nunca se lista nada que requiera autenticación.','Publish manifests'=>'Publicar manifiestos','Serve agent-skills.json, the OpenAPI document and the API catalog.'=>'Servir agent-skills.json, el documento OpenAPI y el catálogo de API.','When disabled, these URLs respond 404.'=>'Cuando está desactivado, estas URLs responden 404.','Contact email'=>'Correo de contacto','Published in the manifests as the technical contact. Defaults to the site admin email.'=>'Se publica en los manifiestos como contacto técnico. Por defecto, el correo del administrador del sitio.','Search content'=>'Buscar contenido','Full-text search across public content. Returns titles, URLs and types.'=>'Búsqueda de texto completo en el contenido público. Devuelve títulos, URLs y tipos.','Search terms.'=>'Términos de búsqueda.','Restrict to "post" (content), "term" or "post-format".'=>'Restringir a "post" (contenido), "term" o "post-format".','Post type, e.g. "post" or "page".'=>'Tipo de contenido, p. ej. "post" o "page".','Results per page (1-100).'=>'Resultados por página (1-100).','Page number.'=>'Número de página.','List %s'=>'Listar %s','Lists published %s with title, excerpt, date and link.'=>'Lista %s publicados con título, extracto, fecha y enlace.','Filter by slug.'=>'Filtrar por slug.','Sort field: date, title, modified, relevance.'=>'Campo de ordenación: date, title, modified, relevance.','"asc" or "desc".'=>'"asc" o "desc".','Read a %s'=>'Leer un elemento de tipo %s','Returns one published %s as JSON with rendered content.'=>'Devuelve un elemento publicado de tipo %s como JSON con el contenido renderizado.','Item id.'=>'Id del elemento.','Read content as Markdown'=>'Leer contenido como Markdown','Any public item is available as Markdown by appending ".md" to its URL, or by requesting its URL with "Accept: text/markdown".'=>'Cualquier elemento público está disponible en Markdown añadiendo ".md" a su URL o solicitando su URL con "Accept: text/markdown".','Any public item is available as Markdown by adding "?wpasl=md" to its URL, or by requesting its URL with "Accept: text/markdown".'=>'Cualquier elemento público está disponible en Markdown añadiendo "?wpasl=md" a su URL o solicitando su URL con "Accept: text/markdown".','Path of the item, as in its canonical URL.'=>'Ruta del elemento, como en su URL canónica.','Site index (llms.txt)'=>'Índice del sitio (llms.txt)','Curated Markdown index of the site with links to the Markdown version of each item.'=>'Índice Markdown curado del sitio con enlaces a la versión Markdown de cada elemento.','API description (OpenAPI 3.1)'=>'Descripción de la API (OpenAPI 3.1)','Machine-readable description of the public REST endpoints listed here.'=>'Descripción legible por máquinas de los endpoints REST públicos listados aquí.','Successful response.'=>'Respuesta correcta.','Not found.'=>'No encontrado.','%s public API'=>'API pública de %s','Read-only endpoints of the WordPress REST API that agents may use without authentication.'=>'Endpoints de solo lectura de la API REST de WordPress que los agentes pueden usar sin autenticación.','The agent manifests are disabled.'=>'Los manifiestos de agente están desactivados.','Diagnostics'=>'Diagnóstico','Simulates how each AI crawler sees this site by requesting the home page, a sample item (as HTML and as Markdown) and the discovery files from this server with the crawler user-agents. Read-only; no external service is contacted.'=>'Simula cómo ve este sitio cada crawler de IA solicitando desde este servidor la portada, un elemento de muestra (como HTML y como Markdown) y los archivos de descubrimiento con los user-agents de los crawlers. Solo lectura; no se contacta ningún servicio externo.','Diagnostics completed.'=>'Diagnóstico completado.','Run crawler simulation'=>'Ejecutar simulación de crawlers','Last report'=>'Último informe','Sample item:'=>'Elemento de muestra:','Infrastructure'=>'Infraestructura','No CDN or proxy detected.'=>'No se detectó CDN ni proxy.','%s detected in front of the site.'=>'%s detectado delante del sitio.','Server header: %s'=>'Cabecera Server: %s','Cloudflare "Markdown for Agents" seems to convert pages at the edge. Keep only one converter (this plugin or Cloudflare) to avoid double processing.'=>'"Markdown for Agents" de Cloudflare parece convertir las páginas en el borde. Conserva un solo conversor (este plugin o Cloudflare) para evitar el doble procesamiento.','Site checks'=>'Comprobaciones del sitio','Per crawler'=>'Por crawler','Crawler'=>'Crawler','robots.txt'=>'robots.txt','Checks'=>'Comprobaciones','OK'=>'OK','Warning'=>'Advertencia','Error'=>'Error','List which AI crawlers you want to allow (see the Crawlers tab) and check that your WAF, bot-fight or "AI scrapers" rules do not block them by user-agent or by ASN.'=>'Define qué crawlers de IA quieres permitir (pestaña Crawlers) y comprueba que tus reglas de WAF, bot-fight o "AI scrapers" no los bloquean por user-agent ni por ASN.','Verify crawlers by IP range or reverse DNS as published by each vendor, rather than trusting the user-agent string alone.'=>'Verifica los crawlers por rango de IP o DNS inverso según publica cada proveedor, en lugar de confiar solo en la cadena user-agent.','Keep rate limiting enabled; raise thresholds for verified crawlers instead of disabling limits site-wide.'=>'Mantén el rate limiting activo; sube los umbrales para crawlers verificados en lugar de desactivar los límites en todo el sitio.','Ensure the CDN or page cache honours "Vary: Accept" for HTML URLs, or rely on the .md URLs which are cached independently.'=>'Asegúrate de que el CDN o la caché de página respetan "Vary: Accept" en las URLs HTML, o apóyate en las URLs .md, que se cachean por separado.','Do not cache or transform robots.txt, llms.txt, agent-skills.json and /.well-known/api-catalog beyond their Cache-Control lifetime.'=>'No caches ni transformes robots.txt, llms.txt, agent-skills.json y /.well-known/api-catalog más allá de su Cache-Control.','If Cloudflare "Markdown for Agents" is enabled, decide whether Cloudflare or this plugin converts pages, not both.'=>'Si "Markdown for Agents" de Cloudflare está activo, decide si convierte Cloudflare o este plugin, no ambos.','Confirm that the uploads/wp-agent-support-layer directory is not directly accessible (Apache .htaccess or an nginx deny rule).'=>'Confirma que el directorio uploads/wp-agent-support-layer no es accesible directamente (.htaccess en Apache o una regla deny en nginx).','After changing security rules, run this simulation again and compare the per-crawler results.'=>'Tras cambiar reglas de seguridad, vuelve a ejecutar esta simulación y compara los resultados por crawler.','Infrastructure checklist (WAF, rate limiting, IP filtering)'=>'Lista de verificación de infraestructura (WAF, rate limiting, filtrado de IP)','This plugin cannot change your CDN or firewall. Review these points with your provider.'=>'Este plugin no puede cambiar tu CDN ni tu firewall. Revisa estos puntos con tu proveedor.','Repeat the checks from outside'=>'Repite las comprobaciones desde fuera','Run these from your computer to see exactly what each crawler receives through your CDN and firewall.'=>'Ejecútalos desde tu equipo para ver exactamente qué recibe cada crawler a través de tu CDN y firewall.','llms.txt'=>'llms.txt','agent-skills.json'=>'agent-skills.json','API catalog'=>'Catálogo de API','Markdown URL of the sample item'=>'URL Markdown del elemento de muestra','Generated documents are publicly accessible by direct URL. Apache: keep the .htaccess in uploads/wp-agent-support-layer. Nginx: add "location ^~ /wp-content/uploads/wp-agent-support-layer/ { deny all; }".'=>'Los documentos generados son accesibles públicamente por URL directa. Apache: conserva el .htaccess en uploads/wp-agent-support-layer. Nginx: añade "location ^~ /wp-content/uploads/wp-agent-support-layer/ { deny all; }".','Direct access to the generated documents is denied.'=>'El acceso directo a los documentos generados está denegado.','Blocked by robots.txt, as configured.'=>'Bloqueado por robots.txt, según la configuración.','Allowed by robots.txt, as configured.'=>'Permitido por robots.txt, según la configuración.','Home page'=>'Portada','Sample item (HTML)'=>'Elemento de muestra (HTML)','Content-Signal header missing on the HTML response (a cache or proxy may strip it).'=>'Falta la cabecera Content-Signal en la respuesta HTML (una caché o proxy puede estar eliminándola).','X-Robots-Tag noai missing on the HTML response.'=>'Falta X-Robots-Tag noai en la respuesta HTML.','Markdown alternate link present.'=>'Enlace alternativo Markdown presente.','No link rel="alternate" type="text/markdown" found (theme without wp_head, or headers stripped).'=>'No se encontró link rel="alternate" type="text/markdown" (tema sin wp_head o cabeceras eliminadas).','Markdown served for Accept: text/markdown.'=>'Markdown servido para Accept: text/markdown.','It appears to be converted by Cloudflare "Markdown for Agents" instead of this plugin; keep only one of the two.'=>'Parece convertido por "Markdown for Agents" de Cloudflare en lugar de por este plugin; conserva solo uno de los dos.','HTML returned for Accept: text/markdown. A page cache or CDN that ignores "Vary: Accept" is probably interfering; agents can still use the .md URL.'=>'Se devolvió HTML para Accept: text/markdown. Probablemente interfiere una caché de página o CDN que ignora "Vary: Accept"; los agentes pueden usar la URL .md.','No public documentation'=>'Sin documentación pública','Crawlers that ignore robots.txt (Bytespider has been reported to) can only be stopped at the firewall or CDN; block them there if you do not want them.'=>'Los crawlers que ignoran robots.txt (se ha reportado que Bytespider lo hace) solo pueden detenerse en el firewall o el CDN; bloquéalos ahí si no los quieres.','A simulation is in progress: %1$d crawler(s) done, %2$d pending. Run it again to continue where it stopped.'=>'Hay una simulación en curso: %1$d crawler(s) completados, %2$d pendientes. Ejecútala de nuevo para continuar donde se detuvo.','Runs in short batches (the page reloads by itself); results are kept for one hour.'=>'Se ejecuta en lotes cortos (la página se recarga sola); los resultados se conservan una hora.','The bundled HTML-to-Markdown library is missing: install a release build or run "composer run build" in the plugin directory.'=>'Falta la librería HTML a Markdown incluida: instala una versión de release o ejecuta "composer run build" en el directorio del plugin.','Post type "%s" is not enabled in the plugin settings (Tools > Agent Support Layer > General).'=>'El tipo de contenido "%s" no está habilitado en los ajustes del plugin (Herramientas > Agent Support Layer > General).','Processed %1$d item(s); %2$d remaining in this cycle.'=>'Procesado(s) %1$d elemento(s); quedan %2$d en este ciclo.','Processed %d item(s) and regenerated the discovery files.'=>'Procesado(s) %d elemento(s) y regenerados los archivos de descubrimiento.','never'=>'nunca','not scheduled'=>'no programado','Storage cleared. All items are pending again.'=>'Almacenamiento vaciado. Todos los elementos vuelven a estar pendientes.','%1$s: HTTP %2$s %3$s'=>'%1$s: HTTP %2$s %3$s','%1$s: unexpected Content-Type "%2$s" (expected %3$s).'=>'%1$s: Content-Type inesperado "%2$s" (se esperaba %3$s).','%1$s: HTTP 200, %2$s.'=>'%1$s: HTTP 200, %2$s.','%s: HTTP 200.'=>'%s: HTTP 200.','%1$s: HTTP %2$d. A WAF, rate limit or bot filter is blocking this user-agent.'=>'%1$s: HTTP %2$d. Un WAF, un límite de peticiones o un filtro de bots está bloqueando este user-agent.','Content-Signal: %s'=>'Content-Signal: %s','X-Robots-Tag: %s'=>'X-Robots-Tag: %s','Accept: text/markdown -> HTTP %1$s %2$s'=>'Accept: text/markdown -> HTTP %1$s %2$s','block'=>'bloquear','allow'=>'permitir','robots.txt could not be read (HTTP %1$s), so the served rules were not verified; the configured policy is "%2$s".'=>'No se pudo leer robots.txt (HTTP %1$s), así que no se verificaron las reglas servidas; la política configurada es "%2$s".','No rule for %1$s in the served robots.txt (configured policy: "%2$s"). A physical robots.txt or a cache may be serving stale rules.'=>'No hay ninguna regla para %1$s en el robots.txt servido (política configurada: "%2$s"). Un robots.txt físico o una caché pueden estar sirviendo reglas obsoletas.','The served robots.txt says "%1$s" for %2$s but the configured policy is "%3$s". A physical robots.txt or a cache may be serving stale rules.'=>'El robots.txt servido indica "%1$s" para %2$s, pero la política configurada es "%3$s". Un robots.txt físico o una caché pueden estar sirviendo reglas obsoletas.','%1$s: HTTP %2$d redirect to %3$s. The diagnostics never follow redirects; crawlers may not either. Serve the content on the canonical host.'=>'%1$s: redirección HTTP %2$d a %3$s. El diagnóstico nunca sigue redirecciones; puede que los crawlers tampoco. Sirve el contenido en el host canónico.','(no Location header)'=>'(sin cabecera Location)','Sitemap'=>'Mapa del sitio','XML sitemap of the whole site.'=>'Mapa del sitio XML de todo el sitio.','Agent skills'=>'Capacidades para agentes','Capabilities an agent can use on this site (JSON-LD).'=>'Capacidades que un agente puede usar en este sitio (JSON-LD).','OpenAPI'=>'OpenAPI','OpenAPI 3.1 description of the public REST API.'=>'Descripción OpenAPI 3.1 de la API REST pública.']];